struct Feature * cJSON_ParseFeature(const char * s) {
    struct Feature * x = NULL;
    if (NULL != s) {
        cJSON * j = cJSON_Parse(s);
        if (NULL != j) {
            x = cJSON_GetFeatureValue(j);
            cJSON_Delete(j);
        }
    }
    return x;
}

struct Feature * cJSON_GetFeatureValue(const cJSON * j) {
    struct Feature * x = NULL;
    if (NULL != j) {
        if (NULL != (x = cJSON_malloc(sizeof(struct Feature)))) {
            memset(x, 0, sizeof(struct Feature));
            if (!cJSON_HasObjectItem(j, "geometry")) { cJSON_DeleteFeature(x); return NULL; }
            if (cJSON_HasObjectItem(j, "geometry")) {
                if (!cJSON_IsObject(cJSON_GetObjectItemCaseSensitive(j, "geometry"))) { cJSON_DeleteFeature(x); return NULL; }
                x->geometry = cJSON_GetGeometryValue(cJSON_GetObjectItemCaseSensitive(j, "geometry"));
                if (NULL == x->geometry) { cJSON_DeleteFeature(x); return NULL; }
            }
            if (!cJSON_HasObjectItem(j, "geometry_name")) { cJSON_DeleteFeature(x); return NULL; }
            if (cJSON_HasObjectItem(j, "geometry_name")) {
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "geometry_name"))) { cJSON_DeleteFeature(x); return NULL; }
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "geometry_name")) || 0 == cJSON_GetGeometryNameValue(cJSON_GetObjectItemCaseSensitive(j, "geometry_name"))) { cJSON_DeleteFeature(x); return NULL; }
                x->geometry_name = cJSON_GetGeometryNameValue(cJSON_GetObjectItemCaseSensitive(j, "geometry_name"));
            }
            if (!cJSON_HasObjectItem(j, "id")) { cJSON_DeleteFeature(x); return NULL; }
            if (cJSON_HasObjectItem(j, "id")) {
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "id"))) { cJSON_DeleteFeature(x); return NULL; }
                x->id = strdup(cJSON_GetStringValue(cJSON_GetObjectItemCaseSensitive(j, "id")));
            }
            else {
                if (NULL != (x->id = cJSON_malloc(sizeof(char)))) {
                    x->id[0] = '\0';
                }
            }
            if (!cJSON_HasObjectItem(j, "properties")) { cJSON_DeleteFeature(x); return NULL; }
            if (cJSON_HasObjectItem(j, "properties")) {
                if (!cJSON_IsObject(cJSON_GetObjectItemCaseSensitive(j, "properties"))) { cJSON_DeleteFeature(x); return NULL; }
                x->properties = cJSON_GetFeaturePropertiesValue(cJSON_GetObjectItemCaseSensitive(j, "properties"));
                if (NULL == x->properties) { cJSON_DeleteFeature(x); return NULL; }
            }
            if (!cJSON_HasObjectItem(j, "type")) { cJSON_DeleteFeature(x); return NULL; }
            if (cJSON_HasObjectItem(j, "type")) {
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "type"))) { cJSON_DeleteFeature(x); return NULL; }
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "type")) || 0 == cJSON_GetFeatureTypeValue(cJSON_GetObjectItemCaseSensitive(j, "type"))) { cJSON_DeleteFeature(x); return NULL; }
                x->type = cJSON_GetFeatureTypeValue(cJSON_GetObjectItemCaseSensitive(j, "type"));
            }
        }
    }
    return x;
}

